shared_html.shared_css:
/* ---------- Shared header / nav ---------- */

.site-nav {
  background: var(--surface);
  color: var(--text);
  border-bottom: 3px double var(--primary);
  font-family: 'Eczar', Georgia, serif;
  position: relative;
}

.site-nav__band {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding: 0.45rem 1.5rem;
  background: var(--text-emphasis);
  color: var(--surface);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.site-nav__kicker {
  font-family: 'Cinzel', serif;
}

.site-nav__wordmark-row {
  display: flex;
  justify-content: center;
  align-items: center;
  padding: 1.6rem 1rem 1.2rem;
  background:
    linear-gradient(var(--surface), var(--surface)),
    var(--surface);
}

.site-nav__wordmark {
  display: inline-flex;
  align-items: center;
  gap: 1.1rem;
  text-decoration: none;
  color: var(--text-emphasis);
}

.site-nav__seal {
  color: var(--primary);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 56px;
  height: 56px;
  border: 1px solid var(--accent);
  border-radius: 50%;
  background: var(--surface);
  box-shadow: inset 0 0 0 3px var(--surface), inset 0 0 0 4px var(--accent);
}

.site-nav__title {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  line-height: 1;
}

.site-nav__title-main {
  font-family: 'Cinzel', serif;
  font-weight: 700;
  font-size: 1.7rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--text-emphasis);
}

.site-nav__title-sub {
  font-family: 'Cinzel', serif;
  font-weight: 500;
  font-size: 0.78rem;
  letter-spacing: 0.42em;
  text-transform: uppercase;
  color: var(--secondary);
  margin-top: 0.5rem;
}

.site-nav__divider {
  height: 6px;
  background:
    repeating-linear-gradient(
      90deg,
      var(--primary) 0 10px,
      var(--accent) 10px 12px,
      var(--primary) 12px 22px,
      transparent 22px 26px
    );
  border-top: 1px solid var(--accent);
  border-bottom: 1px solid var(--accent);
}

.site-nav__divider--double {
  height: 4px;
  background: var(--primary);
  border-top: 1px solid var(--accent);
  border-bottom: 2px solid var(--accent);
  box-shadow: 0 3px 0 var(--primary);
  margin-bottom: 4px;
}

.site-nav__menu ul {
  list-style: none;
  margin: 0;
  padding: 0.9rem 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.2rem 2rem;
  background: var(--surface);
}

.site-nav__menu a {
  font-family: 'Cinzel', serif;
  font-size: 0.82rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  text-decoration: none;
  color: var(--text);
  padding: 0.35rem 0.2rem;
  border-bottom: 1px solid transparent;
  transition: color 0.2s, border-color 0.2s;
}

.site-nav__menu a:hover {
  color: var(--primary);
  border-bottom-color: var(--accent);
}

/* ---------- Shared footer ---------- */

.site-footer {
  background: var(--text-emphasis);
  color: var(--surface);
  font-family: 'Eczar', Georgia, serif;
  margin-top: 4rem;
  border-top: 4px solid var(--primary);
}

.site-footer__divider {
  height: 14px;
  background:
    repeating-linear-gradient(
      90deg,
      var(--accent) 0 2px,
      transparent 2px 6px,
      var(--primary) 6px 8px,
      transparent 8px 14px
    );
  border-bottom: 1px solid var(--accent);
}

.site-footer__arcade {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  gap: 2rem;
  padding: 2.5rem 2rem 1.5rem;
  border-bottom: 1px solid var(--accent);
}

.site-footer__bay {
  position: relative;
  padding: 0 1.2rem;
  font-size: 0.92rem;
  line-height: 1.55;
}

.site-footer__bay:not(.site-footer__bay--center)::before,
.site-footer__bay:not(.site-footer__bay--center)::after {
  content: "";
  position: absolute;
  top: 0;
  bottom: 0;
  width: 2px;
  background: var(--accent);
  opacity: 0.55;
}

.site-footer__bay::before { left: 0; }
.site-footer__bay::after  { right: 0; }

.site-footer__bay p {
  margin: 0 0 0.8rem;
}

.site-footer__heading {
  font-family: 'Cinzel', serif;
  font-size: 0.78rem;
  letter-spacing: 0.3em;
  text-transform: uppercase;
  color: var(--accent);
  margin: 0 0 0.9rem;
  border-bottom: 1px solid var(--accent);
  padding-bottom: 0.4rem;
}

.site-footer__bay--center {
  text-align: center;
  padding: 0 0.5rem;
}

.site-footer__mandala {
  color: var(--accent);
  display: inline-block;
  margin-bottom: 0.6rem;
  /* Animation target: lotus-bloom on the centerpiece seal */
  animation: lotus-bloom 4s ease-in-out infinite;
  transform-origin: 50% 50%;
}

@keyframes lotus-bloom {
  0%, 100% { transform: scale(0.92) rotate(0deg); opacity: 0.85; }
  50%      { transform: scale(1.08) rotate(22.5deg); opacity: 1; }
}

.site-footer__motto {
  font-family: 'Cinzel', serif;
  font-size: 1.05rem;
  letter-spacing: 0.18em;
  color: var(--accent);
  margin: 0.4rem 0 0.2rem;
}

.site-footer__motto-sub {
  font-size: 0.74rem;
  letter-spacing: 0.32em;
  text-transform: uppercase;
  color: var(--surface);
  opacity: 0.75;
  margin: 0;
}

.site-footer__nav ul {
  list-style: none;
  margin: 0;
  padding: 1.2rem 1rem;
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 0.4rem 1.8rem;
  border-bottom: 1px solid var(--accent);
}

.site-footer__nav a {
  font-family: 'Cinzel', serif;
  font-size: 0.74rem;
  letter-spacing: 0.24em;
  text-transform: uppercase;
  color: var(--surface);
  text-decoration: none;
  padding-bottom: 2px;
  border-bottom: 1px solid transparent;
}

.site-footer__nav a:hover {
  color: var(--accent);
  border-bottom-color: var(--accent);
}

.site-footer__colophon {
  text-align: center;
  padding: 1rem 1.5rem 1.6rem;
  font-size: 0.78rem;
  letter-spacing: 0.04em;
  color: var(--surface);
  opacity: 0.78;
}

.site-footer__colophon p {
  margin: 0.25rem 0;
}

@media (max-width: 760px) {
  .site-nav__band { font-size: 0.62rem; padding: 0.4rem 0.8rem; }
  .site-nav__title-main { font-size: 1.25rem; letter-spacing: 0.24em; }
  .site-nav__title-sub  { font-size: 0.66rem; letter-spacing: 0.32em; }
  .site-nav__menu ul { gap: 0.2rem 1.1rem; }
  .site-footer__arcade { grid-template-columns: 1fr; }
  .site-footer__bay::before, .site-footer__bay::after { display: none; }
  .site-footer__bay { border-top: 1px solid var(--accent); padding-top: 1.2rem; }
  .site-footer__bay:first-child { border-top: none; padding-top: 0; }
}
